<script lang="ts">import DashboardContent from '$lib/components/DashboardContent.svelte';import {Button} from '$lib/components/ui/button/index.js';const {data}= $props();let open=$state(false);let selected:any=null;function edit(x:any){selected=x;open=true}function add(){selected={};open=true}</script><DashboardContent title="Teacher Payment Definitions" subtitle="Teaching pay, allowances, committee compensation and other teacher payments are separate payroll lines."><div class="flex justify-end mb-4"><Button onclick={add}>Add payment definition</Button></div><div class="grid gap-4 lg:grid-cols-2">{#each data.definitions as d}<button type="button" onclick={()=>edit(d)} class="rounded-xl border bg-white p-5 text-left shadow-sm hover:border-primary"><div class="flex justify-between"><h2 class="font-bold">{d.name}</h2><span class="text-xs rounded-full bg-slate-100 px-2 py-1">{d.category}</span></div><p class="mt-2 text-sm text-slate-500">{d.calculation_method} · {d.frequency}</p><p class="mt-3 text-xl font-bold">KES {Number(d.amount).toLocaleString()}</p></button>{:else}<div class="rounded-xl border border-dashed p-10 text-center text-slate-500 lg:col-span-2">No teacher payment definitions yet.</div>{/each}</div></DashboardContent>{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"><div class="w-full max-w-lg rounded-2xl bg-white p-6"><h2 class="text-lg font-bold">{selected?.id?'Edit':'Add'} payment definition</h2><form method="POST" action="?/save" class="mt-5 space-y-3"><input type="hidden" name="id" value={selected?.id??''}/><input name="name" required value={selected?.name??''} placeholder="Committee Treasurer Allowance" class="w-full rounded-lg border p-3 text-sm"/><select name="category" value={selected?.category??'allowance'} class="w-full rounded-lg border p-3 text-sm"><option>teaching</option><option>allowance</option><option>committee</option><option>role</option><option>session</option><option>special_assignment</option